package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.Color;
import org.bukkit.Particle;
import org.bukkit.entity.Creeper;
import org.bukkit.event.entity.EntityExplodeEvent;
import org.bukkit.potion.PotionType;

public final class ToxicCreeperBehaviour implements CompiledBehaviour {
    private static final PotionType STRONG_POISON = Registries.entry(RegistryKey.POTION, "minecraft:strong_poison");

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final Particle DUST = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:dust");

    private final MobContext context;

    private Cooldown cooldown;

    public ToxicCreeperBehaviour(MobContext context) {
        this.context = context;
        // node #16 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onExplode(EntityExplodeEvent event) {
        // node #5 event.explode
        // node #6 world.spawn_potion_cloud
        BukkitRuntime.potionCloud(this.context, event.getLocation(), STRONG_POISON, 10, 3.0d, 0.01d, Color.fromRGB(0, 128, 0));
        // node #7
    }

    @Override
    public void onSpawn() {
        // node #12 mob.spawn
        // node #13 creeper.mutate
        ((Creeper) this.context.entity()).setMaxFuseTicks(20);
        // node #14
    }

    @Override
    public void onTick() {
        // node #26 mob.tick
        // node #30 flow.branch
        // node #27 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(250.0d));
        if (!cooldown) return;
        // node #29 world.spawn_particle
        // node #28 mob.self
        final Creeper self = ((Creeper) this.context.entity());
        BukkitRuntime.particles(this.context, self.getWorld(), DUST, self.getEyeLocation(), 5, 1.5d, 1.0d, 1.5d, new Particle.DustOptions(Color.fromRGB(0, 128, 0), 2.0f));
        // node #31
    }
}
